function slugify(title) { return title.toLowerCase().replace(/&/g, "and").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""); }
function buildSections() {
  const sections = [];
  let current = { title: "Introduction", id: "introduction", lines: [] };
  articleLines.forEach((line) => {
    if (h2Titles.includes(line)) { sections.push(current); current = { title: line, id: sectionIds[line] || slugify(line), lines: [] }; return; }
    current.lines.push(line);
  });
  sections.push(current);
  return sections;
}
const allSections = buildSections();
const visibleSections = allSections.filter((section) => section.id !== "faqs");
const faqSection = allSections.find((section) => section.id === "faqs");
function parseFaqs(lines = []) {
  const faqs = [];
  let current = null;
  lines.forEach((line) => {
    if (/^\d+\.\s*/.test(line)) { if (current) faqs.push(current); current = { question: line.replace(/^\d+\.\s*/, ""), answer: [] }; return; }
    if (current) current.answer.push(line);
  });
  if (current) faqs.push(current);
  return faqs.map((faq) => ({ ...faq, answer: faq.answer.join(" ") }));
}
const faqs = parseFaqs(faqSection?.lines);
const references = referencesRaw.split(/\r?\n/).map(cleanSourceLine).filter(Boolean).reduce((items, line, index, lines) => {
  const match = line.match(/^(?:\[(\d+)\]|\s*(\d+)\.)\s*(.+)$/);
  if (!match) return items;
  const url = /^https?:\/\//.test(lines[index + 1] || "") ? lines[index + 1] : "";
  items.push({ n: match[1] || match[2], title: match[3], url });
  return items;
}, []);
const articleLinkRules = [
  { label: "Stress & Digestive Health", href: "/stress-and-digestive-health/", pattern: /Stress (?:&|and) Digestive Health/i },
  { label: "Stress & IBS", href: "/stress-ibs-support-india/", pattern: /Stress (?:&|and) IBS/i },
  { label: "Stress & Acidity", href: "/stress-and-acidity/", pattern: /Stress (?:&|and) Acidity/i },
  { label: "Stress & Migraine", href: "/stress-and-migraine/", pattern: /Stress (?:&|and) Migraine/i },
  { label: "Stress & Headaches", href: "/stress-and-headaches/", pattern: /Stress (?:&|and) Headaches/i },
  { label: "Stress & High Blood Pressure", href: "/stress-and-high-blood-pressure/", pattern: /Stress (?:&|and) High Blood Pressure/i },
  { label: "Stress & Thyroid Health", href: "/stress-and-thyroid/", pattern: /Stress (?:&|and) Thyroid Health/i },
  { label: "Stress & Fatigue", href: "/stress-and-fatigue/", pattern: /Stress (?:&|and) Fatigue/i },
  { label: "Gut-Brain Axis", href: "/stress-and-digestive-health/", pattern: /Gut-Brain Axis/i },
  { label: "Mind-Body Health Assessment", href: "#mind-body-health-assessment-process", pattern: /Mind-Body Health Assessment/i },
  { label: "Mind-Body Health Care", href: "/mind-body-health-care-india/", pattern: /Mind-Body Health Care/i },
  { label: "Neuro-Ayurveda Development System", href: "/about/approach", pattern: /Neuro-Ayurveda Development System/i },
  { label: "Dr. Ankush Garg", href: "/about/doctor", pattern: /Dr\.\s*Ankush Garg/i },
  { label: "Manovaidya", href: "/about/manovaidya", pattern: /Manovaidya/i },
];
const getArticleLinkRuleKey = (rule) => rule.href + "|" + rule.pattern.source;
const lineRuleKeys = new Map();
const globalLinkedRuleKeys = new Set();
function collectLinksForText(text, key) {
  if (!text || subheadingLines.has(text) || h2Titles.includes(text)) return;
  const source = String(text);
  const allowed = new Set();
  let cursor = 0;
  let safety = 0;
  while (cursor < source.length && safety < 100) {
    safety += 1;
    const remaining = source.slice(cursor);
    const candidates = [];
    articleLinkRules.forEach((rule) => {
      const ruleKey = getArticleLinkRuleKey(rule);
      if (globalLinkedRuleKeys.has(ruleKey)) return;
      const match = remaining.match(rule.pattern);
      if (match) candidates.push({ index: match.index, length: match[0].length, ruleKey });
    });
    candidates.sort((a, b) => a.index - b.index || b.length - a.length);
    if (!candidates.length) break;
    const next = candidates[0];
    globalLinkedRuleKeys.add(next.ruleKey);
    allowed.add(next.ruleKey);
    cursor += next.index + next.length;
  }
  if (allowed.size) lineRuleKeys.set(key, allowed);
}
visibleSections.forEach((section) => section.lines.forEach((line, index) => collectLinksForText(line, section.id + "-" + index)));
faqs.forEach((faq, index) => collectLinksForText(faq.answer, "faq-" + index));

