function ContentLine({ line, lineKey, onCitationClick }) {
  if (subheadingLines.has(line)) return <h3 className="mt-5 text-[16px] font-black text-[#21142d]">{line}</h3>;
  let cleaned = line.trim();
  if (cleaned.charCodeAt(0) === 8594) cleaned = cleaned.slice(1).trim();
  if (cleaned.charCodeAt(0) === 9742) cleaned = `Call ${cleaned.slice(1).trim()}`;
  if (cleaned.charCodeAt(0) === 10003) cleaned = cleaned.slice(1).trim();
  if (line.trim().startsWith("Learn More") || line.trim().charCodeAt(0) === 8594 || line.trim().charCodeAt(0) === 9742 || line.trim().charCodeAt(0) === 10003) {
    return <p className="mt-2 flex gap-2 text-[13.5px] font-bold leading-6 text-[#51465a]"><CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-[#7835A4]" /><span><ArticleLinkedText text={cleaned} onCitationClick={onCitationClick} allowedRuleKeys={lineRuleKeys.get(lineKey)} /></span></p>;
  }
  if (line.length < 58 && !/[.!?]$/.test(line) && !line.includes(":")) {
    return <p className="mt-2 flex gap-2 text-[13.5px] font-bold leading-6 text-[#51465a]"><span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-[#7835A4]" /><span><ArticleLinkedText text={line} onCitationClick={onCitationClick} allowedRuleKeys={lineRuleKeys.get(lineKey)} /></span></p>;
  }
  return <p className="mt-3 text-[14px] font-semibold leading-7 text-[#51465a]"><ArticleLinkedText text={line} onCitationClick={onCitationClick} allowedRuleKeys={lineRuleKeys.get(lineKey)} /></p>;
}

